import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"账户管理 - 用户管理","description":"","frontmatter":{"title":"账户管理 - 用户管理"},"headers":[],"relativePath":"ops-knowledge-base/presales-support/user-management.md","filePath":"ops-knowledge-base/presales-support/user-management.md","lastUpdated":1788259091000}'),l={name:"ops-knowledge-base/presales-support/user-management.md"};function s(n,a,i,h,d,p){return t(),r("div",null,[...a[0]||(a[0]=[o('<h2 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h2><p>平台的用户管理功能为用户提供了便捷的账户权限管理和新用户邀请渠道。通过用户管理界面，用户可以清晰查看已有用户的相关信息，并对其权限进行管理。同时，还能邀请新用户加入，灵活分配权限，满足团队协作或多角色管理的需求，提升账户管理的效率与安全性。</p><h2 id="二、用户管理功能" tabindex="-1">二、用户管理功能 <a class="header-anchor" href="#二、用户管理功能" aria-label="Permalink to &quot;二、用户管理功能&quot;">​</a></h2><h3 id="一-功能入口" tabindex="-1">（一）功能入口 <a class="header-anchor" href="#一-功能入口" aria-label="Permalink to &quot;（一）功能入口&quot;">​</a></h3><p>用户可通过 “后台右上角头像/用户管理” 路径，进入用户管理界面，查看和管理已有用户信息。</p><h3 id="二-已有用户信息展示" tabindex="-1">（二）已有用户信息展示 <a class="header-anchor" href="#二-已有用户信息展示" aria-label="Permalink to &quot;（二）已有用户信息展示&quot;">​</a></h3><p>在用户管理界面，以列表形式展示已添加的用户信息，包含以下关键内容：</p><ol><li><strong>电子邮件地址</strong>：显示用户的电子邮箱，作为用户的身份标识之一。</li><li><strong>上次登录时间</strong>：展示用户上次登录平台的时间，帮助用户了解账户的使用活跃度。</li><li><strong>账户角色</strong>：明确标注用户的账户角色，如示例中的 “所有者”，表明该用户对账户具有最高权限。</li><li><strong>操作选项</strong>：针对每个用户，提供 “管理权限” 和 “移除访问” 两个操作按钮。</li></ol><h3 id="三-用户权限管理" tabindex="-1">（三）用户权限管理 <a class="header-anchor" href="#三-用户权限管理" aria-label="Permalink to &quot;（三）用户权限管理&quot;">​</a></h3><ol><li><strong>管理权限</strong>：点击 “管理权限” 按钮，可进入对应用户的权限管理页面，根据业务需求为用户分配或调整各项操作权限，如修改账户信息、管理产品服务等（具体权限内容需根据平台实际设置）。</li><li><strong>移除访问</strong>：若用户不再需要访问平台账户资源，点击 “移除访问” 按钮，即可解除该用户的访问和管理。</li></ol><h2 id="三、邀请新用户功能" tabindex="-1">三、邀请新用户功能 <a class="header-anchor" href="#三、邀请新用户功能" aria-label="Permalink to &quot;三、邀请新用户功能&quot;">​</a></h2><h3 id="一-功能入口-1" tabindex="-1">（一）功能入口 <a class="header-anchor" href="#一-功能入口-1" aria-label="Permalink to &quot;（一）功能入口&quot;">​</a></h3><p>在用户管理界面下方，设有 “邀请新用户” 模块，用户可在此开展新用户邀请操作。</p><h3 id="二-操作流程" tabindex="-1">（二）操作流程 <a class="header-anchor" href="#二-操作流程" aria-label="Permalink to &quot;（二）操作流程&quot;">​</a></h3><ol><li><p><strong>输入邮箱地址</strong>：在输入框中填写受邀者的电子邮箱地址，确保邮箱地址准确无误。</p></li><li><p><strong>选择权限类型</strong>：</p><ul><li><strong>所有权限</strong>：选择此选项，受邀者将获得较高的账户权限，可进行较多的账户操作。</li><li><strong>选择权限</strong>：用户可根据实际需求，灵活勾选具体的权限选项，为受邀者分配定制化的权限。</li></ul></li><li><p><strong>发送邀请</strong>：完成邮箱地址和权限类型选择后，点击 “发送邀请” 按钮，系统将向受邀者的邮箱发送邀请链接。</p></li></ol><h3 id="三-受邀者处理邀请" tabindex="-1">（三）受邀者处理邀请 <a class="header-anchor" href="#三-受邀者处理邀请" aria-label="Permalink to &quot;（三）受邀者处理邀请&quot;">​</a></h3><ol><li><strong>已有账户</strong>：若受邀者已有平台账户，点击邀请链接后，可直接关联至当前账户下，按照分配的权限访问和操作相关内容。</li><li><strong>无账户</strong>：若受邀者没有平台账户，点击邀请链接后可进行账户注册，注册完成后自动加入当前账户体系，依据分配的权限开展操作。</li></ol><p>通过用户管理及邀请新用户功能，平台为用户构建了高效的账户协作与权限管理体系，助力用户便捷管理账户用户，灵活开展团队协作，提升账户使用的安全性与协同性。</p>',18)])])}const c=e(l,[["render",s]]);export{u as __pageData,c as default};
